/* Mandatory rule for robust toggle/hidden state management */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #222034;
  --color-shelf-wood: #663931;
  --color-shelf-highlight: #8f563b;
  --color-shelf-shadow: #45283c;
  --color-accent: #f4b41b;
  --color-accent-hover: #ffd93d;
  --color-card-bg: #323c39;
  --color-text-main: #fbf5ef;
  --color-text-muted: #9badb7;
  --font-stack: 'Courier New', Courier, monospace, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: var(--font-stack);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 24px 12px;
}

.app-container {
  width: 100%;
  max-width: 720px;
  background-color: var(--color-card-bg);
  border: 4px solid #000;
  box-shadow: 
    8px 8px 0px #000,
    inset 2px 2px 0px rgba(255, 255, 255, 0.2),
    inset -2px -2px 0px rgba(0, 0, 0, 0.5);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  text-align: center;
  border-bottom: 4px dashed #1a1e24;
  padding-bottom: 16px;
}

.app-title {
  font-size: 1.8rem;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-shadow: 2px 2px 0px #000;
  margin-bottom: 6px;
}

.app-subtitle {
  font-size: 1rem;
  color: var(--color-text-muted);
}

.control-panel {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  background-color: #24292b;
  padding: 16px;
  border: 3px solid #000;
  box-shadow: inset 2px 2px 0px #000;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1 1 200px;
}

.sort-controls-row {
  display: flex;
  gap: 8px;
}

.control-label {
  font-size: 0.95rem;
  font-weight: bold;
  color: var(--color-text-main);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.pixel-input,
.pixel-select,
.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  height: 42px;
  padding: 6px 10px;
  color: var(--color-text-main);
  background-color: #14171a;
  border: 3px solid #000;
  outline: none;
}

.pixel-input:focus-visible,
.pixel-select:focus-visible,
.pixel-btn:focus-visible {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 2px var(--color-text-main);
}

.pixel-input {
  width: 100%;
}

.pixel-select {
  flex: 1;
  cursor: pointer;
}

.pixel-btn {
  cursor: pointer;
  background-color: var(--color-shelf-wood);
  color: var(--color-text-main);
  font-weight: bold;
  box-shadow: 0 3px 0 #000;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
  padding: 0 16px;
  user-select: none;
}

.pixel-btn:hover {
  background-color: var(--color-shelf-highlight);
}

.pixel-btn:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 #000;
}

.shelf-wrapper {
  position: relative;
  background-color: #1b1928;
  border: 4px solid #000;
  padding: 12px 12px 0 12px;
}

.shelf-plank {
  height: 12px;
  background: repeating-linear-gradient(
    90deg,
    var(--color-shelf-wood),
    var(--color-shelf-wood) 30px,
    var(--color-shelf-highlight) 30px,
    var(--color-shelf-highlight) 34px
  );
  border: 2px solid #000;
}

.top-trim {
  height: 6px;
  margin-bottom: 12px;
  background-color: var(--color-shelf-shadow);
}

.bottom-ledge {
  height: 16px;
  margin-top: 0;
  border-top: 3px solid var(--color-shelf-highlight);
}

.bookshelf-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(68px, 1fr));
  align-items: end;
  gap: 8px;
  min-height: 220px;
  padding-bottom: 2px;
}

.pixel-book {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  padding: 8px 4px;
  border: 3px solid #000;
  box-shadow: 
    inset 2px 0 0 rgba(255, 255, 255, 0.25),
    inset -2px 0 0 rgba(0, 0, 0, 0.4),
    2px 2px 0px rgba(0, 0, 0, 0.5);
  cursor: default;
  position: relative;
  transition: transform 0.1s ease;
}

.pixel-book:hover {
  transform: translateY(-8px);
}

.pixel-book:focus-visible {
  outline: 3px solid var(--color-accent);
  transform: translateY(-8px);
}

.book-spine-title {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 0.85rem;
  font-weight: bold;
  letter-spacing: 0.5px;
  max-height: 120px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #fff;
  text-shadow: 1px 1px 0px #000;
}

.book-spine-year {
  font-size: 0.75rem;
  font-weight: bold;
  background-color: rgba(0, 0, 0, 0.4);
  padding: 2px 4px;
  border-radius: 2px;
  color: var(--color-accent);
  margin-top: 4px;
}

.book-accent-stripes {
  width: 100%;
  height: 4px;
  background-color: var(--color-accent);
  margin-bottom: 6px;
  opacity: 0.8;
}

.empty-message {
  text-align: center;
  padding: 24px;
  font-size: 1.1rem;
  background: #14171a;
  border: 3px dashed var(--color-text-muted);
  color: var(--color-accent);
}

.shelf-stats {
  display: flex;
  justify-content: flex-end;
  font-size: 0.9rem;
  color: var(--color-text-muted);
}

@media (max-width: 480px) {
  .app-container {
    padding: 16px 12px;
  }

  .control-panel {
    padding: 12px;
  }

  .bookshelf-grid {
    grid-template-columns: repeat(4, 1fr);
    gap: 6px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const books = [
    { id: 1, title: 'Neuromancer', author: 'William Gibson', year: 1984, height: 190, color: '#ac3232' },
    { id: 2, title: 'Dune', author: 'Frank Herbert', year: 1965, height: 210, color: '#d95763' },
    { id: 3, title: 'Snow Crash', author: 'Neal Stephenson', year: 1992, height: 185, color: '#5b6ee1' },
    { id: 4, title: 'Foundation', author: 'Isaac Asimov', year: 1951, height: 175, color: '#37946e' },
    { id: 5, title: '1984', author: 'George Orwell', year: 1949, height: 165, color: '#8f974a' },
    { id: 6, title: 'Fahrenheit 451', author: 'Ray Bradbury', year: 1953, height: 180, color: '#df7126' },
    { id: 7, title: 'Ubik', author: 'Philip K. Dick', year: 1969, height: 170, color: '#639bff' },
    { id: 8, title: 'Solaris', author: 'Stanislaw Lem', year: 1961, height: 195, color: '#76428a' }
  ];

  let currentSortKey = 'title';
  let isAscending = true;
  let searchQuery = '';

  const searchInput = document.getElementById('search-input');
  const sortSelect = document.getElementById('sort-select');
  const orderToggleBtn = document.getElementById('order-toggle-btn');
  const booksContainer = document.getElementById('books-container');
  const emptyState = document.getElementById('empty-state');
  const bookCountText = document.getElementById('book-count-text');

  function getFilteredAndSortedBooks() {
    const query = searchQuery.trim().toLowerCase();

    const filtered = books.filter((book) => {
      const matchesTitle = book.title.toLowerCase().includes(query);
      const matchesAuthor = book.author.toLowerCase().includes(query);
      return matchesTitle || matchesAuthor;
    });

    filtered.sort((a, b) => {
      let valA = a[currentSortKey];
      let valB = b[currentSortKey];

      if (typeof valA === 'string') {
        valA = valA.toLowerCase();
        valB = valB.toLowerCase();
        const comparison = valA.localeCompare(valB);
        return isAscending ? comparison : -comparison;
      }

      return isAscending ? valA - valB : valB - valA;
    });

    return filtered;
  }

  function renderBooks() {
    const displayedBooks = getFilteredAndSortedBooks();
    booksContainer.innerHTML = '';

    if (displayedBooks.length === 0) {
      emptyState.hidden = false;
    } else {
      emptyState.hidden = true;
      displayedBooks.forEach((book) => {
        const bookEl = document.createElement('article');
        bookEl.className = 'pixel-book';
        bookEl.setAttribute('role', 'listitem');
        bookEl.tabIndex = 0;
        bookEl.style.height = `${book.height}px`;
        bookEl.style.backgroundColor = book.color;
        bookEl.setAttribute('aria-label', `${book.title} by ${book.author}, published in ${book.year}`);

        const stripes = document.createElement('div');
        stripes.className = 'book-accent-stripes';

        const titleEl = document.createElement('span');
        titleEl.className = 'book-spine-title';
        titleEl.textContent = book.title;

        const yearEl = document.createElement('span');
        yearEl.className = 'book-spine-year';
        yearEl.textContent = book.year;

        bookEl.appendChild(stripes);
        bookEl.appendChild(titleEl);
        bookEl.appendChild(yearEl);
        booksContainer.appendChild(bookEl);
      });
    }

    bookCountText.textContent = `Showing ${displayedBooks.length} of ${books.length} books`;
  }

  searchInput.addEventListener('input', (event) => {
    searchQuery = event.target.value;
    renderBooks();
  });

  sortSelect.addEventListener('change', (event) => {
    currentSortKey = event.target.value;
    renderBooks();
  });

  orderToggleBtn.addEventListener('click', () => {
    isAscending = !isAscending;
    orderToggleBtn.setAttribute('aria-pressed', (!isAscending).toString());
    orderToggleBtn.setAttribute(
      'aria-label',
      `Toggle sort order: currently ${isAscending ? 'ascending' : 'descending'}`
    );
    orderToggleBtn.textContent = isAscending ? 'ASC ▲' : 'DESC ▼';
    renderBooks();
  });

  renderBooks();
});
